#!/usr/bin/env python3
"""Pinned stock client consumes replies generated by two actual ZT Services."""
import argparse,hashlib,inspect,importlib.metadata,json,math,os,subprocess
import sys
from pathlib import Path
from unittest.mock import patch
if not __debug__:raise SystemExit('Refusing disabled assertions')
from bounded_process import run_group,install_termination_handler
install_termination_handler()
import meshtastic
from meshtastic import mesh_interface
from meshtastic.mesh_interface import MeshInterface
from meshtastic.protobuf import mesh_pb2,telemetry_pb2
modes=['unknown','idle','fraction','expired','backward','invalid','lost']
expected_air={'unknown':None,'idle':0,'fraction':600/36000,'expired':0,'backward':None,'invalid':None,'lost':None}
p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=Path);p.add_argument('--output',required=True,type=Path);p.add_argument('--mode',choices=modes,action='append');p.add_argument('--compile-receipt',required=True,type=Path);p.add_argument('--local',action='store_true');a=p.parse_args()
executable=a.executable.resolve();executable_sha256=hashlib.sha256(executable.read_bytes()).hexdigest()
commands=[]
compile_bytes=a.compile_receipt.read_bytes();compiled=json.loads(compile_bytes)
if (compiled.get('status')!='COMPILED_NOT_RUN' or compiled.get('executable_sha256')!=executable_sha256
    or Path(compiled.get('executable','')).resolve()!=executable
    or compiled.get('source_unchanged')is not True or compiled.get('independent_unchanged')is not True
    or compiled.get('fixture')!=('local-telemetry'if a.local else'actual-responder')
    or compiled.get('toolchain_unchanged')is not True or compiled.get('input_manifest_unchanged')is not True
    or compiled.get('independent_sha256',{}).get(Path(__file__).name)!=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    or compiled.get('independent_sha256',{}).get('bounded_process.py')!=hashlib.sha256(Path(__file__).with_name('bounded_process.py').read_bytes()).hexdigest()):
 raise SystemExit('Compile/source/fixture binding mismatch')
assert importlib.metadata.version('meshtastic')=='2.7.11'
client_source=Path(inspect.getsourcefile(mesh_interface)).resolve();assert hashlib.sha256(client_source.read_bytes()).hexdigest()=='8efd6483d8cc1c6a1acb1a6a75efb132a0a1e08a283fb523e83790270c60cc8e'
cache_source=Path(inspect.getsourcefile(meshtastic)).resolve();assert hashlib.sha256(cache_source.read_bytes()).hexdigest()=='697710114181ccdbcdf19c8e4f1a79e6650b87cece5ed5aea8218b782ea3bb6c'
out=a.output.resolve();out.mkdir(exist_ok=False,parents=True)
class Stock(MeshInterface):
 def __init__(self,warm):
  super().__init__(timeout=1);self.currentPacketId=0x59000000;self.myInfo=mesh_pb2.MyNodeInfo(my_node_num=0x12345678)
  self.localNode.nodeNum=0x12345678;self.localNode.localConfig.lora.hop_limit=0
  self.nodesByNum={n:{'num':n,'user':{'id':'!%08x'%n}}for n in (0x12345678,0x87654321)}
  if warm:
   for node in {0x12345678,0x12345678 if a.local else 0x87654321}:self.nodesByNum[node]['deviceMetrics']={'batteryLevel':73,'voltage':3.8,'channelUtilization':3.25,'airUtilTx':1.5,'uptimeSeconds':999}
  self.nodes={v['user']['id']:v for v in self.nodesByNum.values()};self.isConnected.set();self.sent=[];self.callbacks=[]
 def _generatePacketId(self):
  with patch.object(mesh_interface.random,'randint',return_value=0x134400):return super()._generatePacketId()
 def _sendToRadio(self,message):self.sent.append(message.SerializeToString(deterministic=True))
 def onResponseTelemetry(self,packet):self.callbacks.append(packet['decoded']['requestId']);return super().onResponseTelemetry(packet)
receipt={'status':'FAIL','hardware':False,'RF':False,'actual_responder_generation':not a.local,'actual_local_generation':a.local,'local':a.local,'synthetic_peer_data':False,'client_version':'2.7.11','python_optimization':sys.flags.optimize,'python_version':sys.version,'python_executable':str(Path(sys.executable).resolve()),'python_sha256':hashlib.sha256(Path(sys.executable).read_bytes()).hexdigest(),'protobuf_version':importlib.metadata.version('protobuf'),'schema_sha256':{module.__name__:hashlib.sha256(Path(module.__file__).read_bytes()).hexdigest()for module in (mesh_pb2,telemetry_pb2)},'selected_modes':a.mode or modes,'test_source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'executable':str(executable),'executable_sha256':executable_sha256,'compile_receipt_sha256':hashlib.sha256(compile_bytes).hexdigest(),'compile_receipt_bound':True,'client_source_sha256':hashlib.sha256(client_source.read_bytes()).hexdigest(),'cache_source_sha256':hashlib.sha256(cache_source.read_bytes()).hexdigest(),'cases':[]};env={'PATH':'/usr/bin:/bin','LANG':'C','LC_ALL':'C','ASAN_OPTIONS':'detect_leaks=0','UBSAN_OPTIONS':'halt_on_error=1'}
try:
 for mode in a.mode or modes:
  for model in (81,127):
   for transport in ('usb','ble'):
    for warm in (False,True):
     client=Stock(warm)
     with patch.object(client,'waitForTelemetry',return_value=None):client.sendTelemetry(destinationId=0x12345678 if a.local else 0x87654321,wantResponse=True,hopLimit=0)
     assert len(client.sent)==1;request=mesh_pb2.ToRadio.FromString(client.sent[0]).packet
     assert bool(request.decoded.payload)==warm
     if warm:assert telemetry_pb2.Telemetry.FromString(request.decoded.payload).WhichOneof('variant')=='device_metrics'
     argv=[str(executable),client.sent[0].hex(),str(model),transport,mode];commands.append(argv)
     case_log=out/('%s-%d-%s-%s.log'%(mode,model,transport,'warm'if warm else'cold'))
     with case_log.open('w')as log:run_group(argv,stdout=log,env=env,timeout=15)
     records={'USB':[],'BLE':[]};counts=None
     for line in case_log.read_text().splitlines():
      tag,value=line.split(' ',1)
      if tag=='COUNTS':counts=tuple(map(int,value.split()))
      else:records[tag].append(bytes.fromhex(value))
     primed=mode in ('fraction','expired','backward','lost')
     assert counts==((0,int(primed))if a.local else(1,1+int(primed)))
     owner=transport.upper();other='BLE'if owner=='USB'else'USB'
     assert not any(v.HasField('packet')and v.packet.decoded.portnum==67 for v in map(mesh_pb2.FromRadio.FromString,records[other]))
     packets=[v.packet for v in map(mesh_pb2.FromRadio.FromString,records[owner])if v.HasField('packet')and v.packet.decoded.portnum==67]
     assert len(packets)==1;reply=packets[0];assert reply.decoded.request_id==request.id and getattr(reply,'from')==(0x12345678 if a.local else 0x87654321) and reply.to==0x12345678
     metrics=telemetry_pb2.Telemetry.FromString(reply.decoded.payload);v=metrics.device_metrics
     assert metrics.WhichOneof('variant')=='device_metrics' and metrics.time==0 and v.HasField('uptime_seconds')and v.uptime_seconds==321
     assert all(not v.HasField(n)for n in ['battery_level','voltage']),(
      'producer must omit unavailable battery and voltage observations')
     assert v.HasField('channel_utilization') and math.isfinite(v.channel_utilization) and 0<=v.channel_utilization<=100,(
      'independent channel clock must produce a finite in-range channel utilization')
     available=expected_air[mode]is not None
     assert v.HasField('air_util_tx')==available
     if available:assert abs(v.air_util_tx-expected_air[mode])<3e-8
     with patch.object(mesh_interface.publishingThread,'queueWork',side_effect=lambda fn:fn()),patch.object(mesh_interface.pub,'sendMessage',return_value=None),patch.object(mesh_interface,'our_exit',return_value=None):
      for data in records[owner]:client._handleFromRadio(data)
     assert client.callbacks==[request.id] and request.id not in client.responseHandlers and client._acknowledgment.receivedTelemetry
     cache=client.nodesByNum[0x12345678 if a.local else 0x87654321]['deviceMetrics'];assert cache['uptimeSeconds']==321
     # Pinned stock _receiveTelemetry merges fields with dict.update. Omitted
     # battery/voltage fields stay absent cold and retain prior warm values;
     # present channel/airtime fields replace their cached values.
     assert ('airUtilTx'in cache)==(available or warm)
     previous={'batteryLevel':73,'voltage':3.8}
     assert {k:cache[k]for k in previous if k in cache}==(previous if warm else{})
     assert cache.get('channelUtilization')==v.channel_utilization,(
      'stock cache must reflect the fresh channel utilization, not the warm value')
     if warm and not available:assert cache['airUtilTx']==1.5
     if available:assert abs(cache['airUtilTx']-v.air_util_tx)<1e-8
     receipt['cases'].append({'mode':mode,'model':model,'transport':transport,'warm':warm,'status':'PASS','query_sends':counts[0],'responder_sends':counts[1]})
 receipt['status']='PASS'
except BaseException as error:
 receipt['error_type']=type(error).__name__
 if hasattr(error,'owned_process_cleanup'):receipt['owned_process_cleanup']=error.owned_process_cleanup
 if isinstance(error,subprocess.CalledProcessError):receipt['failed_child_exit']=error.returncode
finally:
 receipt['executable_unchanged']=hashlib.sha256(executable.read_bytes()).hexdigest()==executable_sha256
 receipt['fixture_unchanged']=all(hashlib.sha256(Path(__file__).with_name(name).read_bytes()).hexdigest()==compiled['independent_sha256'][name]for name in (Path(__file__).name,'bounded_process.py'))
 receipt['commands']=commands
 if not receipt['executable_unchanged']or not receipt['fixture_unchanged']:receipt['status']='FAIL'
 (out/'SUMMARY.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps({'status':receipt['status'],'cases':len(receipt['cases']),'error_type':receipt.get('error_type')}))
raise SystemExit(receipt['status']!='PASS')
